/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, E, Float, I, Lt, Mul, Pow, Relational, Subs, Sym, add, exp, exptrigsimp, fn, futrig, log, mul, nan, pi, piecewise, pow, rational, simplify, symbols, trigsimp, trigsimpGroebner } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.simplify.trigsimp", () => {
  it("exptrigsimp(exp(z) + exp(-z))", () => {
    const z = new Sym('z');
    expect(sympyStr(exptrigsimp(add(exp(z), exp(mul(-1, z)))))).toBe('2*cosh(z)');
  });
  it("exptrigsimp(cosh(z) - sinh(z))", () => {
    const z = new Sym('z');
    expect(sympyStr(exptrigsimp(add(mul(-1, fn('sinh', [z])), fn('cosh', [z]))))).toBe('exp(-z)');
  });
  it("trigsimp(1/tan(x)**2)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimp(pow(fn('tan', [x]), -2), { old: false, deep: false }))).toBe('tan(x)**(-2)');
  });
  it("trigsimp(e)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimp(add(mul(2, pow(fn('cos', [x]), 2)), mul(2, pow(fn('sin', [x]), 2))), { old: false, deep: false }))).toBe('2');
  });
  it("trigsimp(log(e))", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimp(log(add(mul(2, pow(fn('cos', [x]), 2)), mul(2, pow(fn('sin', [x]), 2)))), { old: false, deep: false }))).toBe('log(2)');
  });
  it("trigsimp(t, method='old') == t", () => {
    const x = new Sym('x');
    expect(sympyStr(add(mul(-2, pow(fn('coth', [x]), -7)), mul(3, pow(fn('tanh', [x]), 7))).equals(add(mul(-2, pow(fn('coth', [x]), -7)), mul(3, pow(fn('tanh', [x]), 7)))))).toBe('True');
  });
  it("trigsimp(t)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimp(add(mul(-2, pow(fn('coth', [x]), -7)), mul(3, pow(fn('tanh', [x]), 7))), { old: false, deep: false }))).toBe('tanh(x)**7');
  });
  it("trigsimp(e, old=True)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimp(add(mul(2, pow(fn('cos', [x]), 2)), mul(2, pow(fn('sin', [x]), 2))), { old: true, deep: false }))).toBe('2');
  });
  it("trigsimp(log(e), old=True)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimp(log(add(mul(2, pow(fn('cos', [x]), 2)), mul(2, pow(fn('sin', [x]), 2)))), { old: true, deep: false }))).toBe('log(2*sin(x)**2 + 2*cos(x)**2)');
  });
  it("trigsimp(log(e), deep=True, old=True)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimp(log(add(mul(2, pow(fn('cos', [x]), 2)), mul(2, pow(fn('sin', [x]), 2)))), { old: true, deep: true }))).toBe('log(2)');
  });
  it("trigsimp(e, old=True) (2)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimp(add(mul(pow(add(1, mul(-1, fn('sin', [x]))), -1), fn('cos', [x])), mul(pow(fn('cos', [x]), -1), add(1, mul(-1, fn('sin', [x]))))), { old: true, deep: false }))).toBe('(1 - sin(x))/cos(x) + cos(x)/(1 - sin(x))');
  });
  it("trigsimp(e, method=\"groebner\", old=True)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimp(add(mul(pow(add(1, mul(-1, fn('sin', [x]))), -1), fn('cos', [x])), mul(pow(fn('cos', [x]), -1), add(1, mul(-1, fn('sin', [x]))))), { old: true, deep: false, method: 'groebner' }))).toBe('2/cos(x)');
  });
  it("trigsimp(1/cot(x)**2, compare=True, old=True)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimp(pow(fn('cot', [x]), -2), { old: true, deep: false }))).toBe('cot(x)**(-2)');
  });
  it("futrig(sinh(x)/tanh(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(futrig(mul(pow(fn('tanh', [x]), -1), fn('sinh', [x]))))).toBe('cosh(x)');
  });
  it("trigsimp_groebner(ex)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimpGroebner(mul(fn('cos', [x]), fn('sin', [x])), {}))).toBe('sin(x)*cos(x)');
  });
  it("trigsimp_groebner(ex, hints=[2])", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimpGroebner(mul(fn('cos', [x]), fn('sin', [x])), { hints: [2] }))).toBe('sin(2*x)/2');
  });
  it("trigsimp_groebner(sin(x)**2 - cos(x)**2, hints=[2])", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimpGroebner(add(pow(fn('sin', [x]), 2), mul(-1, pow(fn('cos', [x]), 2))), { hints: [2] }))).toBe('-cos(2*x)');
  });
  it("trigsimp_groebner(ex, hints=[sin(2*x)])", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimpGroebner(mul(fn('cos', [x]), fn('sin', [x])), { hints: [fn('sin', [mul(2, x)])] }))).toBe('sin(2*x)/2');
  });
  it("trigsimp_groebner(sinh(2*x)/sinh(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimpGroebner(mul(pow(fn('sinh', [x]), -1), fn('sinh', [mul(2, x)])), {}))).toBe('2*cosh(x)');
  });
  it("trigsimp_groebner(sin(x)/cos(x), hints=[tan])", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimpGroebner(mul(pow(fn('cos', [x]), -1), fn('sin', [x])), { hints: ['tan'] }))).toBe('tan(x)');
  });
  it("trigsimp_groebner(sinh(x)/cosh(x), hints=[tanh(x)])", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimpGroebner(mul(pow(fn('cosh', [x]), -1), fn('sinh', [x])), { hints: [fn('tanh', [x])] }))).toBe('tanh(x)');
  });
  it("trigsimp_groebner(ex, hints=[(tan, x, y)])", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(trigsimpGroebner(mul(pow(add(1, mul(-1, fn('tan', [x]), fn('tan', [y]))), -1), add(fn('tan', [x]), fn('tan', [y]))), { hints: [['tan', x, y]] }))).toBe('tan(x + y)');
  });
});

